wyj_SpaceElevator=Class(background)function wyj_SpaceElevator:init()	--	background.init(self,false)	--resource	LoadImageFromFile('SEMin_BG1','wyj_SpaceElevator_BG1.png')	LoadImageFromFile('SEMin_BG2','wyj_SpaceElevator_BG2.png')	LoadImageFromFile('SEMin_BG4','wyj_SpaceElevator_BG4.png')	LoadImageFromFile('SEMin_BG5','wyj_SpaceElevator_BG5.png')	--set 3d camera and fog	Set3D('eye',0,0.0,0.3)	Set3D('at',0,0,-4.8)	Set3D('up',0,1,0)	Set3D('fovy',2)	Set3D('z',0.1,500)	Set3D('fog',300,500,Color(255,0,0,0))	--	self.z=-45	self.an=0	self.xc=0	self.mb=false	self.r=400	self.alx=0	self.cvy=0	self.fovys=2	--New(camera_setter)endfunction wyj_SpaceElevator:frame()    Set3D('at',0,0,-4.8)	Set3D('fovy',self.fovys)	self.z=self.z+2	if self.z==45 then self.z=-45 end	self.an=self.an+0.1	if self.an==360 then self.an=0 end	self.xc=self.xc+2	if self.mb==true and self.alx<1 then self.alx=self.alx+0.005 elseif self.mb==false then self.alx=0 endendfunction wyj_SpaceElevator:render()	SetViewMode'3d'	local m=13	wyj_SpaceElevator.Render_Moon(self.an,self.r,self.alx)	for z=-45,5 do		local c=255		--if z<=-30 then c=sin(90/(abs(z)-29))*255 end		wyj_SpaceElevator.Render_F3(z*15,(z+1)*15,m,self.an,100,c)	end	for z=-45,5 do		local c=255		--if z<=-30 then c=sin(90/(abs(z)-29))*255 end		wyj_SpaceElevator.Render_F1(z*15+self.z,(z+1)*15+self.z,m,self.an+2,50,c,self.alx)	end	SetViewMode'world'endfunction wyj_SpaceElevator.Render_F1(z0,z1,m,an,r,c,a)	for x=0,m-1 do		SetImageState('SEMin_BG1','mul+add',Color((sin(360/m*x)*100+155)*1,c*255,c*46/255,c*60/255))		Render4V('SEMin_BG1',cos(360/m*x+an)*r							,sin(360/m*x+an)*r							,z0							,cos(360/m*(x+1)+an)*r							,sin(360/m*(x+1)+an)*r							,z0							,cos(360/m*(x+1)+an)*r							,sin(360/m*(x+1)+an)*r							,z1							,cos(360/m*x+an)*r							,sin(360/m*x+an)*r							,z1)	endendfunction wyj_SpaceElevator.Render_Moon(an,r,a)	SetImageState('SEMin_BG2','',Color(255,255,255,255))	SetImageState('SEMin_BG5','mul+add',Color(a*255,255,255,255))	Render4V('SEMin_BG5',cos(an+135)*700,sin(an+135)*1400,-200						,cos(an+45)*700,sin(an+45)*1400,-200						,cos(an+315)*700,sin(an+315)*1400,-200						,cos(an+225)*700,sin(an+225)*1400,-200)	Render4V('SEMin_BG2',cos(an+135)*r/4.3,sin(an+135)*r/4.3,-375						,cos(an+45)*r/4.3,sin(an+45)*r/4.3,-375						,cos(an+315)*r/4.3,sin(an+315)*r/4.3,-375						,cos(an+225)*r/4.3,sin(an+225)*r/4.3,-375)endfunction wyj_SpaceElevator.Render_F3(z0,z1,m,an,r,c)	for x=0,m-1 do		SetImageState('SEMin_BG4','mul+add',Color(sin(360/m*x)*100+155,c,c,c))		Render4V('SEMin_BG4',cos(360/m*x+an)*r							,sin(360/m*x+an)*r							,z0							,cos(360/m*(x+1)+an)*r							,sin(360/m*(x+1)+an)*r							,z0							,cos(360/m*(x+1)+an)*r							,sin(360/m*(x+1)+an)*r							,z1							,cos(360/m*x+an)*r							,sin(360/m*x+an)*r							,z1)	endend